const getClassColorIndex = (className = '', classList = []) => {
  const normalized = String(className || '미배정').trim().toUpperCase();
  if (!normalized || normalized === '미배정') return -1;

  const normalizedList = Array.from(new Set(
    (Array.isArray(classList) ? classList : [])
      .map(name => String(name || '').trim().toUpperCase())
      .filter(Boolean)
  ));

  const sortedList = normalizedList.length
    ? normalizedList.sort((a, b) => a.localeCompare(b, 'ko'))
    : [normalized];

  const foundIndex = sortedList.indexOf(normalized);
  if (foundIndex >= 0) return foundIndex;

  return normalized.split('').reduce((sum, char) => sum + char.charCodeAt(0), 0);
};

const getClassVisualStyle = (className = '', classList = []) => {
  const normalized = String(className || '미배정').trim();

  if (!normalized || normalized === '미배정' || normalized === '-') {
    return {
      text: '#64748b',
      bg: '#f8fafc',
      border: '#e2e8f0',
      badge: 'bg-slate-50 text-slate-600 border-slate-200'
    };
  }

  const index = getClassColorIndex(normalized, classList);
  return CLASS_COLOR_PALETTE[Math.abs(index) % CLASS_COLOR_PALETTE.length];
};

const calculateTimeDiff = (timeIn, timeOut) => {
  if (!timeIn || !timeOut) return '-';
  const parse = (t) => { const parts = t.split(':'); return parseInt(parts[0] || 0) * 60 + parseInt(parts[1] || 0); };
  let inMins = parse(timeIn); let outMins = parse(timeOut);
  if (outMins < inMins) outMins += 24 * 60; 
  const diff = outMins - inMins;
  if (isNaN(diff) || diff <= 0) return '-';
  return `${Math.floor(diff / 60)}시간 ${diff % 60}분`;
};

const parseTimeDiffToMins = (timeIn, timeOut) => {
  if (!timeIn || !timeOut) return 0;
  const parse = (t) => { const parts = t.split(':'); return parseInt(parts[0] || 0) * 60 + parseInt(parts[1] || 0); };
  let inMins = parse(timeIn); let outMins = parse(timeOut);
  if (outMins < inMins) outMins += 24 * 60; 
  const diff = outMins - inMins;
  return (isNaN(diff) || diff <= 0) ? 0 : diff;
};

const formatMinsToTime = (mins) => {
    if (!mins) return '0시간 0분';
    return `${Math.floor(mins / 60)}시간 ${mins % 60}분`;
};

const calculateTotalStudyTime = (dailyArray) => {
  let totalMins = 0;
  dailyArray.forEach(d => { totalMins += parseTimeDiffToMins(d.in, d.out); });
  return formatMinsToTime(totalMins);
};

const getStudyTimeStats = (student) => {
    let totalMins = 0;
    let daysStudied = 0;
    MONTHS.forEach(m => {
        const daily = student.studyTime[m] || [];
        daily.forEach(d => {
            const diff = parseTimeDiffToMins(d.in, d.out);
            if (diff > 0) { totalMins += diff; daysStudied++; }
        });
    });
    const avgMins = daysStudied > 0 ? Math.floor(totalMins / daysStudied) : 0;
    return { totalStr: formatMinsToTime(totalMins), totalMins, avgStr: formatMinsToTime(avgMins), daysStudied };
};

const emptyMonthlyScore = { score: '', percent: '', classRank: '', totalRank: '', trackAvg: '', top30Avg: '', trackAvgDiff: '', top30Diff: '' };

const generateEmptyMonthlyData = () => {
  const data = {}; 
  MONTHS.forEach(m => { data[m] = { english: { ...emptyMonthlyScore }, math: { ...emptyMonthlyScore }, total: { ...emptyMonthlyScore } }; }); 
  return data;
};

const generateEmptyMonthlyAttendance = () => {
    const data = {};
    MONTHS.forEach(m => {
        data[m] = {
            am: Array(31).fill(''),
            pm: Array(31).fill(''),
            amMemo: Array(31).fill(''),
            pmMemo: Array(31).fill('')
        };
    });
    return data;
};

const generateEmptyMonthlyStudyTime = () => {
    const data = {};
    MONTHS.forEach(m => { data[m] = Array.from({length: 31}, () => ({in: '', out: ''})); });
    return data;
}

const generateEmptyMonthlyDaily = () => {
    const data = {};
    MONTHS.forEach(m => {
        data[m] = Array.from({ length: 31 }, () => ({ t1: '', t2: '', math: '' }));
    });
    return data;
}

const createStudent = (id, userId, name, startMonth, targetTrack, mEng, mMath, wEng, wMath, monData) => {
    const baseMonthly = generateEmptyMonthlyData();
    if(monData) {
        Object.keys(monData).forEach(m => {
            if(baseMonthly[m]) {
                baseMonthly[m] = {
                    english: { ...baseMonthly[m].english, ...(monData[m].english || {}) },
                    math: { ...baseMonthly[m].math, ...(monData[m].math || {}) },
                    total: { ...baseMonthly[m].total, ...(monData[m].total || {}) }
                }
            }
        });
    }

    return {
      id, userId, name, startMonth: startMonth || '1월', className: "GB1A", classNames: ["GB1A"], gender: id.includes("586") ? "여" : "남",
      contact: "010-0000-0000", parentContact: "010-1111-1111", address: "대구/경북",
      university: "대학교", major: "전공", gradStatus: "재학/휴학", transferType: "일반",
      targetTrack, credits: 70, gpa: "3.5", motivation: "학벌", englishScore: "토익",
      notes: "", consulting: { "4월": "성실하게 진행 중." },
      studyTime: generateEmptyMonthlyStudyTime(),
      attendance: generateEmptyMonthlyAttendance(),
      dailyRecords: generateEmptyMonthlyDaily(),
      scores: { 
          mockEnglish: mEng || {}, mockMath: mMath || {}, 
          weeklyEnglish: wEng || {}, weeklyMath: wMath || {}, 
          monthly: baseMonthly, weeklyDetails: {}, weeklyDetailsMath: {} 
      }
    }
};

const normalizeMonthlyAttendanceData = (attendance = {}) => {
  const base = generateEmptyMonthlyAttendance();
  const result = {};

  MONTHS.forEach(month => {
    const monthData = attendance?.[month] || {};
    result[month] = {
      ...base[month],
      ...monthData,
      am: Array.isArray(monthData.am) ? monthData.am : base[month].am,
      pm: Array.isArray(monthData.pm) ? monthData.pm : base[month].pm,
      amMemo: Array.isArray(monthData.amMemo) ? monthData.amMemo : base[month].amMemo,
      pmMemo: Array.isArray(monthData.pmMemo) ? monthData.pmMemo : base[month].pmMemo
    };
  });

  return result;
};

const normalizeMonthlyStudyTimeData = (studyTime = {}) => {
  const base = generateEmptyMonthlyStudyTime();
  const result = {};

  MONTHS.forEach(month => {
    result[month] = Array.isArray(studyTime?.[month])
      ? studyTime[month].map(day => ({ in: '', out: '', ...(day || {}) }))
      : base[month];
  });

  return result;
};

const normalizeMonthlyDailyData = (dailyRecords = {}) => {
  const base = generateEmptyMonthlyDaily();
  const result = {};

  MONTHS.forEach(month => {
    result[month] = Array.isArray(dailyRecords?.[month])
      ? dailyRecords[month].map(day => ({ t1: '', t2: '', math: '', ...(day || {}) }))
      : base[month];
  });

  return result;
};

const normalizeMonthlyScoresData = (monthly = {}) => {
  const base = generateEmptyMonthlyData();
  const result = {};

  MONTHS.forEach(month => {
    const monthData = monthly?.[month] || {};
    result[month] = {
      english: {
        ...base[month].english,
        ...(monthData.english || {})
      },
      math: {
        ...base[month].math,
        ...(monthData.math || {})
      },
      total: {
        ...base[month].total,
        ...(monthData.total || {})
      }
    };
  });

  return result;
};

const normalizeStudentData = (student = {}) => {
  const safeId = String(student.id || student.userId || `S-${Date.now()}_${Math.random().toString(36).slice(2, 8)}`);
  const safeName = String(student.name || '이름없음').trim() || '이름없음';

  const classList = Array.isArray(student.classNames)
    ? student.classNames.filter(Boolean)
    : [student.className].filter(Boolean);

  const safeClassNames = classList.length ? classList : ['미배정'];
  const safeClassName = student.className || safeClassNames[0] || '미배정';
  const scores = student.scores || {};

  return {
    ...student,
    id: safeId,
    userId: student.userId || '',
    name: safeName,
    startMonth: student.startMonth || '1월',
    className: safeClassName,
    classNames: safeClassNames,
    gender: student.gender || '',
    contact: student.contact || '',
    parentContact: student.parentContact || '',
    address: student.address || '',
    university: student.university || '',
    major: student.major || '',
    gradStatus: student.gradStatus || '',
    transferType: student.transferType || '일반',
    targetTrack: student.targetTrack || '미정',
    credits: student.credits ?? '',
    gpa: student.gpa ?? '',
    motivation: student.motivation || '',
    englishScore: student.englishScore || '',
    notes: student.notes || '',
    consulting: student.consulting || {},
    attendance: normalizeMonthlyAttendanceData(student.attendance || {}),
    studyTime: normalizeMonthlyStudyTimeData(student.studyTime || {}),
    dailyRecords: normalizeMonthlyDailyData(student.dailyRecords || {}),
    scores: {
      ...scores,
      mockEnglish: scores.mockEnglish || {},
      mockMath: scores.mockMath || {},
      weeklyEnglish: scores.weeklyEnglish || {},
      weeklyMath: scores.weeklyMath || {},
      weeklyDetails: scores.weeklyDetails || {},
      weeklyDetailsMath: scores.weeklyDetailsMath || {},
      weeklyMeta: scores.weeklyMeta || {},
      monthly: normalizeMonthlyScoresData(scores.monthly || {})
    }
  };
};

